/**
 * The images every Academy website has from the day it is published
 * (SEO/AEO/GEO pass, Nov 2026), generated by the backend from the
 * Academy's name and brand colour:
 *
 *   - `og-image.png` — the 1200×630 share card, the `og:image` /
 *     `twitter:image` of every page whose owner set none (a shared link
 *     otherwise showed no picture at all);
 *   - `icon.png?size=N` — a square monogram: the `apple-touch-icon`, and
 *     the favicon of an Academy that uploaded none (the platform's own
 *     icon used to stand for the Academy in browser tabs and results).
 *
 * `v` is `brandImageVersion(name, colour)`: a new name or colour is a new
 * URL, so caches never show the old picture; the backend computes the same
 * value and lets that exact URL be cached for a year.
 */
import { ENV } from '@config';
import type { HostnameResolution } from '@types';
import { academyFaviconHref } from '../hooks/useAcademyFavicon';

/** FNV-1a (32-bit) of `name + "\0" + colour`, as 8 hex digits — mirrored by the backend (`brand-images.util.ts`). */
export function brandImageVersion(
  name: string,
  color: string | undefined
): string {
  const input = `${name}\u0000${color ?? ''}`;
  let hash = 0x811c9dc5;
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}

/** The API's base on `origin` (the canonical origin): absolute, as `og:image` must be. */
function absoluteApiBase(origin: string, apiBaseUrl: string): string {
  const base = apiBaseUrl.replace(/\/+$/, '');
  return /^https?:\/\//i.test(base)
    ? base
    : `${origin.replace(/\/+$/, '')}${base}`;
}

function academyPath(academyId: string): string {
  return `/public/websites/${encodeURIComponent(academyId)}`;
}

/** The colour the generated images are drawn in: the website's public brand colour (the hostname lookup's `presentation`, as the backend reads it). */
export type BrandImageAcademy = Pick<
  HostnameResolution,
  'academyId' | 'academyName' | 'presentation'
>;

function versionOf(academy: BrandImageAcademy): string {
  return brandImageVersion(
    academy.academyName,
    academy.presentation?.brand.primaryColor
  );
}

/** The absolute URL of the Academy's generated 1200×630 share card. */
export function academyOgImageUrl(
  academy: BrandImageAcademy,
  origin: string,
  apiBaseUrl: string = ENV.apiBaseUrl
): string {
  return `${absoluteApiBase(origin, apiBaseUrl)}${academyPath(academy.academyId)}/og-image.png?v=${versionOf(academy)}`;
}

/**
 * The Academy's generated square monogram, `size` px (same-origin, like
 * the favicon route): 180 is the `apple-touch-icon`, 96 the favicon of an
 * Academy that uploaded none (Google asks for a multiple of 48 px).
 */
export function academyMonogramIconHref(
  academy: BrandImageAcademy,
  size: 96 | 180,
  apiBaseUrl: string = ENV.apiBaseUrl
): string {
  return `${apiBaseUrl.replace(/\/+$/, '')}${academyPath(academy.academyId)}/icon.png?size=${size}&v=${versionOf(academy)}`;
}

/** The tab icon: the Academy's own favicon, else its monogram — never the platform's icon on an Academy's site. */
export function academyIconHref(
  academy: BrandImageAcademy & Pick<HostnameResolution, 'faviconVersion'>,
  apiBaseUrl: string = ENV.apiBaseUrl
): string {
  return (
    academyFaviconHref(academy, apiBaseUrl) ??
    academyMonogramIconHref(academy, 96, apiBaseUrl)
  );
}

/**
 * An owner-set image URL as an absolute one on `origin` (`og:image` must be
 * absolute); `undefined` for anything a crawler cannot fetch (a `data:` URI,
 * a non-http scheme).
 */
export function absoluteImageUrl(
  value: string | undefined,
  origin: string
): string | undefined {
  if (!value) return undefined;
  if (/^https?:\/\//i.test(value)) return value;
  if (value.startsWith('/') && !value.startsWith('//')) {
    return `${origin.replace(/\/+$/, '')}${value}`;
  }
  return undefined;
}
